    (*args).test_iter = TEST_BOOTSTRAP_TEST_DEFAULT_ITERATIONS;
    // Default coll iteration is 1
    (*args).coll_iter = TEST_BOOTSTRAP_COLL_DEFAULT_ITERATIONS;
    // Default collective is ALL
    (*args).coll = "ALL";
